#include <stdio.h>

#define SIZE 3

int items[SIZE];
int front = 0, count = 0;

int enqueue(int value) {
    if (count == SIZE) {
        return 0;
    }
    items[(front + count) % SIZE] = value;
    count++;
    return 1;
}

int dequeue() {
    int value = items[front];
    front = (front + 1) % SIZE;
    count--;
    return value;
}

int main() {
    enqueue(1);
    enqueue(2);
    enqueue(3);
    printf("%d\n", dequeue());
    printf("enqueue 4: %d\n", enqueue(4));
    printf("%d\n", dequeue());
    printf("%d\n", dequeue());
    printf("%d\n", dequeue());
    return 0;
}
